mapper.select:
select l.*, m.material_name, m.material_cd, m.is_bonded, m.g_model, m.code_ts,
       (select round(timestampdiff(hour, min(l2.create_time), now()) / 24, 1)
        from br_stock_ledger l2 where l2.material_id = l.material_id) as stock_days
from br_stock_ledger l
left join br_material m on m.id = l.material_id

    AND l.material_id = #{materialId}
    AND m.material_cd like concat('%', #{materialCd}, '%')
    AND m.material_name like concat('%', #{materialName}, '%')
    AND m.g_model like concat('%', #{gModel}, '%')
    AND m.code_ts like concat('%', #{codeTs}, '%')
    AND l.mark_type = #{markType}
    AND l.mark_type in #{mt}
    AND m.is_bonded in #{ib}
    AND l.biz_type = #{bizType}
    AND l.biz_no like concat('%', #{bizNo}, '%')
    AND l.work_no = #{workNo}
    AND l.batch_no = #{batchNo}
    AND l.create_time >= #{beginTime}
    AND l.create_time < date_add(#{endTime}, interval 1 day)



    order by l.id asc
    order by l.id desc

select mark_type, sum(case when biz_type = 'IN' then qty else 0 end) as in_qty, sum(case when biz_type = 'ISSUE' then qty else 0 end) as issue_qty, sum(case when biz_type = 'RCV' then qty else 0 end) as rcv_qty, sum(case when biz_type = 'OUT' then qty else 0 end) as out_qty, sum(qty) as balance from br_stock_ledger
AND batch_no = #{batchNo} AND work_no = #{workNo}
group by mark_type
